    export type BOMArgs<ExtArgs extends $Extensions.InternalArgs = $Extensions.DefaultArgs> = BOMDefaultArgs<ExtArgs>
    /**
     * @deprecated Use BOMItemDefaultArgs instead
     */
    export type BOMItemArgs<ExtArgs extends $Extensions.InternalArgs = $Extensions.DefaultArgs> = BOMItemDefaultArgs<ExtArgs>
    /**
     * @deprecated Use ProductionOrderDefaultArgs instead
     */
    export type ProductionOrderArgs<ExtArgs extends $Extensions.InternalArgs = $Extensions.DefaultArgs> = ProductionOrderDefaultArgs<ExtArgs>
    /**
     * @deprecated Use ProductionOrderItemDefaultArgs instead
     */
    export type ProductionOrderItemArgs<ExtArgs extends $Extensions.InternalArgs = $Extensions.DefaultArgs> = ProductionOrderItemDefaultArgs<ExtArgs>

  /**
   * Batch Payload for updateMany & deleteMany & createMany
   */

